INSERT INTO risk_rules (rule_version_id, rule_id, rule_name, version, description, base_weight, params, effective_from, effective_to, created_by, status) VALUES
('RULE-001-v1','RULE-001','VELOCITY_SPIKE',1,'Burst of debit transactions on one account inside a short window.',40.00,'{"cooldown_hours": 24, "min_debit_count": 6, "window_minutes": 60}','2026-01-01T00:00:00',NULL,'USR-007','ACTIVE'),
('RULE-002-v1','RULE-002','NEW_DEVICE_HIGH_VALUE',1,'High-value debit made from a device first linked to the account <= 24h earlier. v2 (2026-07-01) lowers the amount threshold after an admin review.',35.00,'{"cooldown_hours": 24, "min_amount": 25000.0, "window_hours": 24}','2026-01-01T00:00:00','2026-07-01T00:00:00','USR-007','RETIRED'),
('RULE-002-v2','RULE-002','NEW_DEVICE_HIGH_VALUE',2,'High-value debit made from a device first linked to the account <= 24h earlier. v2 (2026-07-01) lowers the amount threshold after an admin review.',35.00,'{"cooldown_hours": 24, "min_amount": 20000.0, "window_hours": 24}','2026-07-01T00:00:00',NULL,'USR-007','ACTIVE'),
('RULE-003-v1','RULE-003','CIRCULAR_TRANSFER',1,'Funds return to the originating account through a chain of 2-4 transfers within 72h (each leg >= min amount and within tolerance of the first leg). Base score depends on cycle length.',0.00,'{"amount_tolerance": 0.15, "base_by_len": {"2": 35.0, "3": 55.0, "4": 65.0}, "max_len": 4, "min_leg_amount": 20000.0, "min_len": 2, "window_hours": 72}','2026-01-01T00:00:00',NULL,'USR-007','ACTIVE'),
('RULE-004-v1','RULE-004','DORMANT_REACTIVATION',1,'First transaction after >= 180 days of inactivity is a high-value debit.',45.00,'{"dormancy_days": 180, "min_amount": 15000.0}','2026-01-01T00:00:00',NULL,'USR-007','ACTIVE');
